mapper.insert:
insert into conversation_session (
  session_id, user_id, title, status, kb_scope, asset_scope, created_at, updated_at
) values (
  #{sessionId}, #{userId}, #{title}, #{status}, #{kbScope}, #{assetScope}, #{createdAt}, #{updatedAt}
)

mapper.select:
select session_id, user_id, title, status, kb_scope, asset_scope, created_at, updated_at
from conversation_session
where user_id = #{userId}
  and deleted_at is null

  and (
    updated_at < #{beforeUpdatedAt}
    or (updated_at = #{beforeUpdatedAt} and session_id < #{beforeSessionId})
  )

order by updated_at desc, session_id desc
limit #{limit}

mapper.update:
update conversation_session
set title = #{generatedTitle},
    updated_at = greatest(timestampadd(microsecond, 1000, updated_at), #{requestStartedAt})
where session_id = #{sessionId}
  and deleted_at is null
  and title <=> #{expectedTitle}

mapper.select:
select turn_id, created_at
from conversation_turn
where session_id = #{sessionId}
  and turn_id = #{turnId}
  and deleted_at is null

select turn_id, session_id, query, answer, asset_scope, answer_mode, answer_status, answer_fallback_reason, intent_type, intent_confidence, intent_reason, intent_source, intent_fallback, citations, retrieval_trace, agent_run_id, workflow_version, execution_mode, agent_task_id, created_at from conversation_turn where session_id = #{sessionId} and deleted_at is null
and ( created_at < #{beforeCreatedAt} or (created_at = #{beforeCreatedAt} and turn_id < #{beforeTurnId}) )
order by created_at desc, turn_id desc limit #{limit}
